      when 1 then format('Em %s, um item aborda “%s…”. Qual princípio deve orientar a interpretação?', seed.topic_name, left(seed.point, 48))
      when 2 then format('Um relatório de %s examina “%s…” em condições diferentes. Qual procedimento produz a análise mais sólida?', seed.topic_name, left(seed.point, 48))
      when 3 then format('Em uma questão avançada de %s sobre “%s…”, dois argumentos disputam a explicação. Qual conclusão é metodologicamente defensável?', seed.topic_name, left(seed.point, 48))
      when 4 then format('Uma resposta sobre “%s…” em %s foi criticada por ignorar uma condição relevante. Qual revisão melhora o raciocínio?', left(seed.point, 48), seed.topic_name)
      else format('Ao transferir “%s…” de %s para outra situação, qual decisão demonstra compreensão rigorosa?', left(seed.point, 48), seed.topic_name)    end as prompt,
    case f.form_index
      when 1 then seed.point
      when 2 then format('Usar o princípio apresentado como hipótese e conferir dados pertinentes, contexto e explicações alternativas: %s', seed.point)
      when 3 then format('Concluir apenas até onde as evidências e condições permitem, aplicando o princípio: %s', seed.point)
      when 4 then format('Reformular a análise para incorporar o princípio e explicitar seus limites: %s', seed.point)
      else format('Aplicar o princípio ao contexto, monitorar consequências e rever a decisão diante de novas evidências: %s', seed.point)
    end as answer,
    case f.form_index
      when 1 then format('A afirmação preserva a relação central: %s', seed.point)
      when 2 then format('A análise combina o princípio com dados adequados e comparação de explicações: %s', seed.point)
      when 3 then format('A conclusão aplica o princípio sem extrapolar o alcance das informações: %s', seed.point)
      when 4 then format('A revisão incorpora o princípio e torna explícitos os limites da inferência: %s', seed.point)
      else format('A transferência mantém o princípio e verifica se as condições e consequências mudaram: %s', seed.point)
    end as explanation,
    case f.form_index
      when 1 then jsonb_build_array('Aplicar o princípio sem considerar o contexto ou as condições descritas.', 'Usar um único exemplo como prova de que a conclusão vale para todos os casos.', 'Substituir evidências pela interpretação mais conveniente quando há incerteza.')
      when 2 then jsonb_build_array('Selecionar apenas registros que confirmem a hipótese e omitir os divergentes.', 'Tratar uma associação observada como causa comprovada sem investigação adicional.', 'Generalizar para qualquer população sem verificar se as condições são comparáveis.')
      when 3 then jsonb_build_array('Escolher a hipótese mais simples mesmo quando contradiz dados relevantes.', 'Afirmar causalidade ou certeza universal a partir de uma observação isolada.', 'Descartar explicações alternativas sem comparar suas previsões com os dados.')
      when 4 then jsonb_build_array('Manter a conclusão imune a contraexemplos e a novos dados.', 'Substituir justificativa por opinião de autoridade sem evidência pertinente.', 'Atribuir o resultado a uma causa única antes de examinar outras variáveis.')
      else jsonb_build_array('Copiar a solução de outro contexto sem verificar condições, riscos ou população afetada.', 'Maximizar um indicador isolado mesmo que prejudique outros resultados relevantes.', 'Presumir que a recomendação funciona para todos sem medir consequências ou rever a decisão.')
    end as wrong,
    (((seed.concept_index + f.form_index - 2) % 4) + 1)::smallint as correct_position,
    case when ((seed.concept_index - 1) * 5 + f.form_index) = 1 then 1
         when ((seed.concept_index - 1) * 5 + f.form_index) <= 4 then 2
         when ((seed.concept_index - 1) * 5 + f.form_index) <= 9 then 3
         when ((seed.concept_index - 1) * 5 + f.form_index) <= 16 then 4
         else 5 end::smallint as difficulty
  from concept_seed as seed
  cross join forms as f
  where not (
    (seed.topic_slug = 'matematica-funcoes-graficos' and seed.concept_index = 5 and f.form_index = 5)
    or (seed.topic_slug = 'matematica-geometria-espacial' and seed.concept_index = 5 and f.form_index = 5)
    or (seed.topic_slug = 'matematica-geometria-espacial' and seed.concept_index = 5 and f.form_index = 4)
    or (seed.topic_slug = 'matematica-estatistica-probabilidade' and seed.concept_index = 5 and f.form_index = 5)
    or (seed.topic_slug = 'fisica-mecanica' and seed.concept_index = 5 and f.form_index = 5)
    or (seed.topic_slug = 'biologia-ecologia' and seed.concept_index = 5 and f.form_index = 5)
    or (seed.topic_slug = 'quimica-solucoes-organica' and seed.concept_index = 5 and f.form_index = 5)
    or (seed.topic_slug = 'biologia-genetica-evolucao' and seed.concept_index = 5 and f.form_index = 5)
    or (seed.topic_slug = 'fisica-mecanica' and seed.concept_index = 5 and f.form_index = 4)
    or (seed.topic_slug = 'biologia-ecologia' and seed.concept_index = 5 and f.form_index = 4)
    or (seed.topic_slug = 'fisica-eletricidade-ondas' and seed.concept_index = 5 and f.form_index = 5)
    or (seed.topic_slug = 'fisica-ondas-acustica' and seed.concept_index = 5 and f.form_index = 5)
    or (seed.topic_slug = 'quimica-eletroquimica-pilhas' and seed.concept_index = 5 and f.form_index = 5)
    or (seed.topic_slug = 'quimica-solucoes-organica' and seed.concept_index = 5 and f.form_index = 4)
    or (seed.topic_slug = 'biologia-fisiologia-humana' and seed.concept_index = 5 and f.form_index = 5)
    or (seed.topic_slug = 'matematica-aritmetica-porcentagem' and seed.concept_index = 5 and f.form_index = 5)
    or (seed.topic_slug = 'matematica-geometria-espacial' and seed.concept_index = 5 and f.form_index = 3)
    or (seed.topic_slug = 'matematica-estatistica-probabilidade' and seed.concept_index = 5 and f.form_index = 4)
    or (seed.topic_slug = 'matematica-aritmetica-porcentagem' and seed.concept_index = 5 and f.form_index = 4)
    or (seed.topic_slug = 'matematica-algebra-funcoes' and seed.concept_index = 5 and f.form_index = 5)
    or (seed.topic_slug = 'matematica-funcoes-graficos' and seed.concept_index = 5 and f.form_index = 4)
    or (seed.topic_slug = 'literatura-poesia-voz-imagens' and seed.concept_index = 5 and f.form_index = 5)
    or (seed.topic_slug = 'filosofia-antiga-moderna' and seed.concept_index = 5 and f.form_index = 5)
    or (seed.topic_slug = 'portugues-generos' and seed.concept_index = 5 and f.form_index = 5)
    or (seed.topic_slug = 'arte-brasileira' and seed.concept_index = 5 and f.form_index = 5)
    or (seed.topic_slug = 'educacao-fisica-inclusao-esporte' and seed.concept_index = 5 and f.form_index = 5)
    or (seed.topic_slug = 'sociologia-cultura-identidade' and seed.concept_index = 5 and f.form_index = 5)
    or (seed.topic_slug = 'literatura-brasileira' and seed.concept_index = 5 and f.form_index = 5)
    or (seed.topic_slug = 'artes-patrimonio-cultura' and seed.concept_index = 5 and f.form_index = 5)
    or (seed.topic_slug = 'portugues-variacao-registros' and seed.concept_index = 5 and f.form_index = 5)
    or (seed.topic_slug = 'educacao-fisica-danca-lutas' and seed.concept_index = 5 and f.form_index = 5)
    or (seed.topic_slug = 'sociologia-cidadania' and seed.concept_index = 5 and f.form_index = 5)
    or (seed.topic_slug = 'sociologia-midia-tecnologia' and seed.concept_index = 5 and f.form_index = 5)
    or (seed.topic_slug = 'artes-patrimonio-cultura' and seed.concept_index = 5 and f.form_index = 4)
    or (seed.topic_slug = 'redacao-intervencao' and seed.concept_index = 5 and f.form_index = 5)
  )
),
original_seed as (
  select topic_slug, prompt, difficulty, correct_position,
    case correct_position
      when 1 then jsonb_build_array(answer, wrong -> 0, wrong -> 1, wrong -> 2)
      when 2 then jsonb_build_array(wrong -> 0, answer, wrong -> 1, wrong -> 2)
      when 3 then jsonb_build_array(wrong -> 0, wrong -> 1, answer, wrong -> 2)
      else jsonb_build_array(wrong -> 0, wrong -> 1, wrong -> 2, answer)
    end as options,
    explanation, 'original'::text as origin_type,
    'Questão autoral · estilo ENEM e vestibulares'::text as origin_label,
    null::text as origin_exam, null::text as origin_url, null::text as origin_license
  from expanded
),
official_seed as (
  select * from jsonb_to_recordset($official_seed$[{"topic_slug":"matematica-funcoes-graficos","prompt":"Adaptada do ENEM 2025: uma cooperativa registra quatro safras. As áreas foram 180, 200, 220 e 240 hectares; as produtividades foram 35, 40, 35 e 45 sacas de 50 kg por hectare. Qual sequência representa a produção, em toneladas?","difficulty":4,"correct_position":1,"options":["315, 400, 385 e 540","630, 800, 770 e 1 080","315, 385, 400 e 540","350, 440, 540 e 500","630, 400, 770 e 540"],"explanation":"Multiplica-se área por sacas por hectare e por 50 kg, convertendo para toneladas. A produção é 315, 400, 385 e 540 t. Os dados e a formulação desta versão são diferentes do item-fonte.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 167 · CC BY 4.0","origin_exam":"ENEM 2025 — 2º dia, caderno 5, questão 167","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"matematica-geometria-espacial","prompt":"Adaptada do ENEM 2025: serão fabricadas 100 medalhas cilíndricas de diâmetro 10 cm e espessura 2 mm. Em cada uma, um prisma de base quadrada atravessa o cilindro; a diagonal do quadrado mede 10 cm. A parte externa ao prisma será revestida. Usando π = 3,14, qual volume total de revestimento é necessário?","difficulty":5,"correct_position":2,"options":["285 cm³","570 cm³","785 cm³","1 000 cm³","1 570 cm³"],"explanation":"A área do círculo é 78,5 cm². O quadrado com diagonal 10 cm tem área 50 cm². Como a espessura é 0,2 cm, o volume total é 100 × (78,5 − 50) × 0,2 = 570 cm³.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 168 · CC BY 4.0","origin_exam":"ENEM 2025 — 2º dia, caderno 5, questão 168","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"matematica-geometria-espacial","prompt":"Adaptada do ENEM 2025: uma caixa de descarga mede 3 dm × 2 dm na base e tem coluna de água de 1,5 dm. Para reduzir o consumo, serão submersas garrafas vedadas que deslocam 0,4 L cada. A descarga ainda deve liberar pelo menos 6 L. Qual é o número máximo de garrafas?","difficulty":5,"correct_position":3,"options":["5","6","7","8","9"],"explanation":"A caixa comporta 9 L. Restam 3 L para deslocamento sem reduzir a descarga abaixo de 6 L. Com 0,4 L por garrafa, cabem no máximo 7 garrafas (2,8 L); 8 deslocariam 3,2 L.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 174 · CC BY 4.0","origin_exam":"ENEM 2025 — 2º dia, caderno 5, questão 174","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"matematica-estatistica-probabilidade","prompt":"Adaptada do ENEM 2025: oito livros diferentes, entre eles um atlas e uma biografia, serão distribuídos a três estudantes. A estudante mais velha receberá três livros, o mais novo também três, e o terceiro ficará com os dois restantes. A mais velha receberá exatamente um dos dois livros especiais. De quantas formas isso pode ocorrer?","difficulty":5,"correct_position":3,"options":["150","240","300","360","560"],"explanation":"Há 2 escolhas para o livro especial da estudante mais velha, C(6,2)=15 escolhas para os outros dois livros dela e C(5,3)=10 escolhas para os três do mais novo. O total é 2 × 15 × 10 = 300.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 179 · CC BY 4.0","origin_exam":"ENEM 2025 — 2º dia, caderno 5, questão 179","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"fisica-mecanica","prompt":"Adaptada do ENEM 2025: uma atleta percorre 5 km em 40 minutos de uma prova. Nos 24 minutos seguintes, mantém a mesma velocidade média. Qual distância total ela percorre nesses 64 minutos?","difficulty":4,"correct_position":3,"options":["6 km","7 km","8 km","9 km","10 km"],"explanation":"A velocidade média é 5/40 = 0,125 km/min. Em 64 minutos, a distância total é 0,125 × 64 = 8 km.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 180 · CC BY 4.0","origin_exam":"ENEM 2025 — 2º dia, caderno 5, questão 180","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"biologia-ecologia","prompt":"Adaptada do ENEM 2025: uma espécie de lagarto de ambiente árido conserva água e pode passar longos períodos sem alimento. Em qual bioma brasileiro condições de seca prolongada tornam mais provável encontrar adaptações semelhantes?","difficulty":4,"correct_position":3,"options":["Amazônia","Pantanal","Caatinga","Pampa","Mata Atlântica"],"explanation":"A Caatinga tem clima semiárido e longos períodos secos, condições que favorecem adaptações relacionadas à economia de água e à escassez sazonal de alimento.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 95 · CC BY 4.0","origin_exam":"ENEM 2025 — 2º dia, caderno 5, questão 95","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"quimica-solucoes-organica","prompt":"Adaptada do ENEM 2025: após um processo que remove sais dissolvidos, uma água é usada como solvente em laboratório e em baterias. O processo também retira íons necessários à ingestão regular. Qual tipo de água corresponde a essa descrição?","difficulty":2,"correct_position":3,"options":["Água dura","Água mineral","Água destilada","Água salobra","Água oxigenada"],"explanation":"A destilação remove sais dissolvidos. A água destilada é útil em aplicações laboratoriais e técnicas, mas não é indicada como fonte habitual de minerais na alimentação.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 96 · CC BY 4.0","origin_exam":"ENEM 2025 — 2º dia, caderno 5, questão 96","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"biologia-genetica-evolucao","prompt":"Adaptada do ENEM 2025: em uma espécie de inseto, o alelo A determina cor escura e domina sobre a. Dois indivíduos heterozigotos são cruzados. Qual proporção fenotípica é esperada entre os descendentes, considerando dominância completa?","difficulty":4,"correct_position":5,"options":["1 escuro : 1 claro","1 escuro : 2 intermediários : 1 claro","2 escuros : 1 claro","9 escuros : 3 claros","3 escuros : 1 claro"],"explanation":"No cruzamento Aa × Aa, os genótipos esperados são 1 AA : 2 Aa : 1 aa. Com dominância completa, AA e Aa têm cor escura, resultando em 3 escuros para 1 claro.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 102 · CC BY 4.0","origin_exam":"ENEM 2025 — 2º dia, caderno 5, questão 102","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"fisica-mecanica","prompt":"Adaptada do ENEM 2025: uma caixa desliza de um piso horizontal para uma rampa retilínea de inclinação constante. O coeficiente de atrito cinético não muda. Como se compara a força de atrito na rampa com a força no piso horizontal?","difficulty":4,"correct_position":3,"options":["Aumenta continuamente ao longo da rampa.","Permanece igual porque a rugosidade não mudou.","Diminui ao entrar na rampa e permanece constante nela.","Torna-se nula durante todo o movimento na rampa.","Aumenta porque o peso do objeto cresce na subida."],"explanation":"Na rampa, a normal vale mg cos(θ), menor que mg no piso horizontal. Como o atrito cinético é μN e o ângulo é constante, ele diminui na transição e permanece constante ao longo da rampa.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 103 · CC BY 4.0","origin_exam":"ENEM 2025 — 2º dia, caderno 5, questão 103","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"biologia-ecologia","prompt":"Adaptada do ENEM 2025: a água usada para resfriar uma usina retorna mais quente a um rio. Qual efeito pode comprometer organismos aquáticos mesmo sem a descarga de uma substância tóxica?","difficulty":4,"correct_position":5,"options":["Aumentar a solubilidade do oxigênio na água.","Eliminar a variação diária de temperatura.","Converter sais dissolvidos em nutrientes.","Reduzir a atividade metabólica de todos os organismos a zero.","Diminuir o oxigênio dissolvido e alterar as condições de vida."],"explanation":"O aquecimento da água reduz a solubilidade do oxigênio e pode alterar o metabolismo e as condições de sobrevivência de espécies aquáticas, caracterizando poluição térmica.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 107 · CC BY 4.0","origin_exam":"ENEM 2025 — 2º dia, caderno 5, questão 107","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"fisica-eletricidade-ondas","prompt":"Adaptada do ENEM 2025: um aparelho de resistência R funciona com tensão V, mas a fonte disponível fornece 1,2V. Para manter V no aparelho, qual resistor de proteção deve ser ligado em série?","difficulty":5,"correct_position":5,"options":["Um resistor em paralelo de resistência 0,2R.","Um resistor em série de resistência 0,8R.","Um resistor em série de resistência 1,2R.","Um resistor em paralelo de resistência 0,8R.","Um resistor em série de resistência 0,2R."],"explanation":"Para a tensão no aparelho permanecer V, a corrente deve ser V/R. O resistor em série deve dissipar a diferença 0,2V; assim, Rₚ = 0,2V ÷ (V/R) = 0,2R.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 113 · CC BY 4.0","origin_exam":"ENEM 2025 — 2º dia, caderno 5, questão 113","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"fisica-ondas-acustica","prompt":"Adaptada do ENEM 2025: um sensor interrompe um feixe de 15 cm de largura. O menor perfil de uma pessoa tem 20 cm de espessura, e a velocidade máxima considerada é 5 m/s. Qual tempo de resposta garante detectar a passagem mais rápida?","difficulty":4,"correct_position":2,"options":["20 ms","70 ms","150 ms","300 ms","700 ms"],"explanation":"A interrupção dura ao menos (0,15 + 0,20) m ÷ 5 m/s = 0,07 s, ou 70 ms. O sensor deve responder em até esse intervalo para registrar a passagem.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 118 · CC BY 4.0","origin_exam":"ENEM 2025 — 2º dia, caderno 5, questão 118","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"quimica-eletroquimica-pilhas","prompt":"Adaptada do ENEM 2025: uma peça de prata escurecida por sulfeto de prata é colocada em solução salina em contato com alumínio. Qual processo redox permite recuperar a prata metálica?","difficulty":4,"correct_position":2,"options":["A prata metálica oxida e o alumínio também oxida.","O alumínio oxida, fornecendo elétrons para reduzir o sulfeto de prata.","O cloreto reduz o alumínio e oxida a prata.","A água fornece elétrons para oxidar o sulfeto de prata.","O sulfeto de prata se converte em prata sem transferência de elétrons."],"explanation":"O alumínio perde elétrons (oxida) e os fornece à espécie de prata, que os recebe e é reduzida a Ag metálica. A solução permite o transporte iônico no processo.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 126 · CC BY 4.0","origin_exam":"ENEM 2025 — 2º dia, caderno 5, questão 126","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"quimica-solucoes-organica","prompt":"Adaptada do ENEM 2025: um filtro usa carvão ativado poroso para remover compostos orgânicos da água. Qual propriedade explica a maior eficiência em relação a um carvão com superfície pouco porosa?","difficulty":4,"correct_position":4,"options":["Maior massa para o mesmo volume.","Maior dureza macroscópica.","Menor capacidade de conduzir calor.","Maior área superficial disponível para adsorção.","Maior densidade do material."],"explanation":"A porosidade amplia muito a área de contato. Mais moléculas podem aderir à superfície do carvão por adsorção, aumentando a remoção de contaminantes.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 132 · CC BY 4.0","origin_exam":"ENEM 2025 — 2º dia, caderno 5, questão 132","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"biologia-fisiologia-humana","prompt":"Adaptada do ENEM 2025: genes que controlam um ciclo circadiano são inseridos em uma bactéria que não tinha esse relógio biológico. Se os genes inseridos se expressam, quais funções são esperadas no organismo modificado?","difficulty":4,"correct_position":4,"options":["Somente o metabolismo da bactéria receptora.","O ciclo circadiano próprio da receptora, sem alteração do metabolismo.","O metabolismo do organismo doador e o relógio da receptora.","O ciclo circadiano do doador e o metabolismo da bactéria receptora.","Somente o ciclo circadiano do organismo doador."],"explanation":"Os genes transferidos carregam a informação associada ao relógio circadiano do organismo doador, enquanto a bactéria receptora mantém seu próprio metabolismo.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 133 · CC BY 4.0","origin_exam":"ENEM 2025 — 2º dia, caderno 5, questão 133","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"matematica-aritmetica-porcentagem","prompt":"Adaptada do ENEM 2025: uma cantina compara o sódio total por pacote. Os rótulos indicam: I, 90 mg por porção e 4 porções; II, 120 mg e 3 porções; III, 55 mg e 5 porções; IV, 130 mg e 2 porções; V, 50 mg e 6 porções. Qual pacote tem menos sódio?","difficulty":4,"correct_position":4,"options":["I","II","III","IV","V"],"explanation":"Os totais são, respectivamente, 360, 360, 275, 260 e 300 mg. O pacote IV tem a menor quantidade total, apesar de ter mais sódio por porção que alguns outros.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 140 · CC BY 4.0","origin_exam":"ENEM 2025 — 2º dia, caderno 5, questão 140","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"matematica-geometria-espacial","prompt":"Adaptada do ENEM 2025: uma peça é formada por um prisma hexagonal regular e um tronco de pirâmide hexagonal, unidos pelas bases congruentes de contato. As duas bases externas têm tamanhos diferentes. Quantas cores são necessárias para pintar faces congruentes com a mesma cor e faces não congruentes com cores distintas?","difficulty":5,"correct_position":4,"options":["3","5","6","4","12"],"explanation":"Há quatro classes de faces: retângulos laterais do prisma, trapézios laterais do tronco, base hexagonal externa do prisma e base hexagonal externa do tronco. As duas bases externas têm dimensões diferentes.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 141 · CC BY 4.0","origin_exam":"ENEM 2025 — 2º dia, caderno 5, questão 141","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"matematica-estatistica-probabilidade","prompt":"Adaptada do ENEM 2025: em uma amostra de 100 internautas, 40 são homens e 75 acessam uma rede social. Entre os homens, 30 acessam a rede. Escolhendo uma pessoa ao acaso, qual é a probabilidade de ela ser homem e acessar a rede?","difficulty":4,"correct_position":2,"options":["10%","30%","40%","75%","90%"],"explanation":"O evento conjunto inclui 30 pessoas entre as 100 da amostra. Portanto, a probabilidade é 30/100 = 30%.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 145 · CC BY 4.0","origin_exam":"ENEM 2025 — 2º dia, caderno 5, questão 145","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"matematica-aritmetica-porcentagem","prompt":"Adaptada do ENEM 2025: um carro percorre 30 km por dia durante sete dias e consome 1 m³ de GNV a cada 13 km. Para garantir apenas um abastecimento semanal, qual cilindro tem a menor capacidade suficiente entre 10, 14, 17, 21 e 25 m³?","difficulty":4,"correct_position":3,"options":["10 m³","14 m³","17 m³","21 m³","25 m³"],"explanation":"A distância semanal é 210 km. O consumo é 210/13 ≈ 16,15 m³; portanto, a menor capacidade suficiente é 17 m³.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 146 · CC BY 4.0","origin_exam":"ENEM 2025 — 2º dia, caderno 5, questão 146","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"matematica-algebra-funcoes","prompt":"Adaptada do ENEM 2025: uma escola teve 25% das matrículas em francês em 2023. Em 2024, totalizou 80 matrículas. Se o total de 2025 permanecer em 80 e a distribuição voltar às proporções de 2023, quantas matrículas serão em francês?","difficulty":4,"correct_position":5,"options":["8","12","16","18","20"],"explanation":"Mantendo a proporção de 25% sobre 80 matrículas, obtém-se 0,25 × 80 = 20 matrículas.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 149 · CC BY 4.0","origin_exam":"ENEM 2025 — 2º dia, caderno 5, questão 149","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"matematica-funcoes-graficos","prompt":"Adaptada do ENEM 2025: uma tela mostra cinco deslocamentos. I: 4 cm na escala 1:100; II: 3 cm em 1:200; III: 5 cm em 1:100; IV: 2 cm em 1:400; V: 7 cm em 1:100. Qual deslocamento real foi maior?","difficulty":4,"correct_position":3,"options":["I, com 4 m","II, com 6 m","IV, com 8 m","V, com 7 m","III, com 5 m"],"explanation":"Multiplicando cada comprimento desenhado pelo denominador da escala: I=4 m, II=6 m, III=5 m, IV=8 m e V=7 m. O maior é IV.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 150 · CC BY 4.0","origin_exam":"ENEM 2025 — 2º dia, caderno 5, questão 150","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"literatura-poesia-voz-imagens","prompt":"Adaptada do ENEM 2025: um poema contrapõe lembranças de liberdade na infância às restrições da vida adulta e repete um pedido de liberdade. Que efeito a repetição produz no conjunto?","difficulty":4,"correct_position":2,"options":["Transforma a voz poética em narrador neutro.","Reforça a tensão entre a infância imaginada e os limites presentes.","Enumera ações sem estabelecer relação entre os tempos.","Elimina a dimensão afetiva do poema.","Apresenta uma definição literal de liberdade."],"explanation":"A repetição conecta as imagens da infância ao desejo de liberdade e torna mais forte o contraste com as restrições da vida adulta.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 1 · CC BY 4.0","origin_exam":"ENEM 2025 — 1º dia, caderno 2, questão 1 (opção Espanhol)","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"filosofia-antiga-moderna","prompt":"Adaptada do ENEM 2025: uma filósofa defende que a reflexão deve ajudar a enfrentar pobreza, opressão e doutrinação. Qual concepção de filosofia está expressa?","difficulty":4,"correct_position":3,"options":["Uma atividade isolada de problemas humanos.","Uma técnica para provar que todo conflito tem solução única.","Uma investigação ligada à vida e à transformação de condições sociais.","Um conjunto de regras que dispensa debate público.","Uma disciplina restrita à classificação de conceitos abstratos."],"explanation":"A posição vincula a reflexão filosófica aos problemas concretos e à possibilidade de transformar condições de vida.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 3 · CC BY 4.0","origin_exam":"ENEM 2025 — 1º dia, caderno 2, questão 3","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"portugues-generos","prompt":"Adaptada do ENEM 2025: uma cronista compara bilhetes manuscritos, originais datilografados e textos digitais. Qual conclusão reconhece melhor as mudanças nos modos de escrita?","difficulty":4,"correct_position":3,"options":["Uma tecnologia nova sempre elimina a anterior.","A escrita manual só existe em contextos sem acesso à internet.","Os suportes e modos de escrita podem coexistir e atender a necessidades distintas.","A autenticidade de um texto depende exclusivamente da caligrafia.","A escrita digital impede qualquer interação pessoal."],"explanation":"A história dos suportes mostra transformações e coexistência: novas tecnologias ampliam possibilidades sem apagar automaticamente práticas anteriores.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 6 · CC BY 4.0","origin_exam":"ENEM 2025 — 1º dia, caderno 2, questão 6","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"arte-brasileira","prompt":"Adaptada do ENEM 2025: uma exposição apresenta retratos nomeados de lideranças negras e indígenas pouco representadas em coleções tradicionais. Que efeito essa escolha pode produzir?","difficulty":4,"correct_position":3,"options":["Reforçar que somente grupos dominantes podem ser retratados.","Retirar a arte do debate sobre memória social.","Afirmar identidades e tornar visíveis sujeitos historicamente marginalizados.","Substituir pesquisa histórica por uma leitura exclusivamente decorativa.","Provar que as desigualdades de representação já foram superadas."],"explanation":"Dar nome e protagonismo a sujeitos pouco representados amplia a memória visual e questiona desigualdades na construção da história da arte.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 11 · CC BY 4.0","origin_exam":"ENEM 2025 — 1º dia, caderno 2, questão 11","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"educacao-fisica-inclusao-esporte","prompt":"Adaptada do ENEM 2025: uma transmissão esportiva celebra histórias individuais de superação, mas não mostra barreiras de acesso, seleção e condições de treinamento. Qual análise é mais consistente?","difficulty":4,"correct_position":2,"options":["O esporte de alto rendimento já é acessível a todas as pessoas.","A narrativa motivacional pode ocultar limites e desigualdades da prática esportiva.","A mídia é incapaz de influenciar a imagem pública do esporte.","Diferenças de desempenho provam falta de esforço individual.","A inclusão depende somente de ampliar o tempo de transmissão."],"explanation":"A celebração de casos excepcionais pode esconder barreiras estruturais e custos humanos presentes no esporte de alto rendimento.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 14 · CC BY 4.0","origin_exam":"ENEM 2025 — 1º dia, caderno 2, questão 14","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"sociologia-cultura-identidade","prompt":"Adaptada do ENEM 2025: uma campanha mostra crianças imaginando profissões diferentes e discute como o racismo limita expectativas sociais. Qual objetivo melhor descreve a ação?","difficulty":4,"correct_position":2,"options":["Substituir políticas educacionais por escolhas individuais.","Sensibilizar a sociedade para os efeitos do racismo e para a importância de combatê-lo.","Defender que certas profissões pertencem a grupos específicos.","Promover orientação profissional sem discutir desigualdade.","Afirmar que a discriminação não afeta trajetórias de vida."],"explanation":"A campanha relaciona estereótipos raciais a oportunidades e procura sensibilizar para os benefícios de enfrentar a discriminação.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 18 · CC BY 4.0","origin_exam":"ENEM 2025 — 1º dia, caderno 2, questão 18","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"literatura-brasileira","prompt":"Adaptada do ENEM 2025: em um romance brasileiro do século XIX, um pai anuncia que negociou o casamento da filha sem que ela tenha participado da decisão. Que leitura social o episódio permite sustentar?","difficulty":5,"correct_position":3,"options":["A autonomia feminina era plena nas relações familiares rurais.","O casamento aparece como escolha exclusivamente individual da jovem.","A autoridade patriarcal condiciona decisões privadas e a autonomia da personagem.","O conflito elimina todas as convenções sociais do período.","O narrador apresenta a relação familiar como desprovida de hierarquia."],"explanation":"A negociação feita pelo pai evidencia uma estrutura patriarcal na qual a vontade da jovem é subordinada à autoridade familiar.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 20 · CC BY 4.0","origin_exam":"ENEM 2025 — 1º dia, caderno 2, questão 20","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"artes-patrimonio-cultura","prompt":"Adaptada do ENEM 2025: um povo indígena usa urucum em práticas cotidianas de proteção e relaciona a planta a seres e narrativas de seu território. Como interpretar esse uso?","difficulty":4,"correct_position":2,"options":["Como decoração sem relação com conhecimentos coletivos.","Como prática cultural que articula ambiente, cosmologia e proteção.","Como evidência de que todos os povos indígenas compartilham a mesma crença.","Como substituição recente de toda relação com plantas cultivadas.","Como ritual sem significado para a vida comunitária."],"explanation":"O uso do urucum integra conhecimentos ambientais, cosmologia e práticas de proteção; não se reduz a um ornamento.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 24 · CC BY 4.0","origin_exam":"ENEM 2025 — 1º dia, caderno 2, questão 24","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"portugues-variacao-registros","prompt":"Adaptada do ENEM 2025: uma reportagem lista nomes regionais diferentes para preparações culinárias semelhantes. O que essa diversidade evidencia?","difficulty":4,"correct_position":2,"options":["Uma disputa que define uma única forma correta de nomear o prato.","Variação lexical ligada a regiões e comunidades de fala.","A impossibilidade de compreender palavras fora da região de origem.","Uma mudança exclusivamente gramatical, sem relação com cultura.","A ausência de padrões locais de uso da língua."],"explanation":"As denominações mostram variação lexical associada a regiões e práticas culturais, sem tornar uma variedade superior às demais.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 31 · CC BY 4.0","origin_exam":"ENEM 2025 — 1º dia, caderno 2, questão 31","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"educacao-fisica-danca-lutas","prompt":"Adaptada do ENEM 2025: em uma prática de luta, os participantes reconhecem a habilidade e a intenção combativa do oponente, seguem regras e controlam a força. O que a distingue de uma briga?","difficulty":4,"correct_position":3,"options":["A existência obrigatória de medalhas.","O fato de nunca haver contato físico.","A presença de regras, reconhecimento do outro e controle da ação.","A ausência de objetivos ou técnicas compartilhadas.","A intenção de causar dano sem considerar o adversário."],"explanation":"A luta é uma prática corporal organizada: regras e reconhecimento do oponente orientam o confronto, diferentemente da violência desumanizadora de uma briga.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 32 · CC BY 4.0","origin_exam":"ENEM 2025 — 1º dia, caderno 2, questão 32","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"sociologia-cidadania","prompt":"Adaptada do ENEM 2025: uma liderança indígena articula reivindicações por território, educação e saúde e prepara novas lideranças comunitárias. Que dimensão da cidadania aparece nesse processo?","difficulty":4,"correct_position":2,"options":["Cidadania como documento formal, sem participação coletiva.","Direitos exercidos por mobilização, reconhecimento e continuidade da organização política.","Representação política restrita a indivíduos sem vínculos comunitários.","Substituição dos direitos territoriais por ações assistenciais temporárias.","Abandono das instituições e dos direitos sociais."],"explanation":"A ação articula participação política coletiva, direitos sociais e reconhecimento territorial, mostrando que cidadania depende também de sua efetivação.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 37 · CC BY 4.0","origin_exam":"ENEM 2025 — 1º dia, caderno 2, questão 37","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"sociologia-midia-tecnologia","prompt":"Adaptada do ENEM 2025: o rádio manteve público mesmo após a expansão da televisão e de plataformas digitais, adaptando formatos e alcançando regiões com outros níveis de conectividade. Qual conclusão é sustentada?","difficulty":4,"correct_position":2,"options":["Uma tecnologia sempre substitui completamente a anterior.","Meios de comunicação podem coexistir e se adaptar a públicos e condições diferentes.","A internet eliminou diferenças de acesso à informação.","O rádio deixou de ter função social após a televisão.","A escolha de um meio depende somente da idade do público."],"explanation":"A permanência do rádio mostra que tecnologias podem coexistir e atender a condições de acesso e usos distintos.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 40 · CC BY 4.0","origin_exam":"ENEM 2025 — 1º dia, caderno 2, questão 40","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"artes-patrimonio-cultura","prompt":"Adaptada do ENEM 2025: um banco ritual de um povo amazônico é transmitido entre gerações e aparece em narrativas de origem. Por que ele é patrimônio cultural para essa comunidade?","difficulty":5,"correct_position":2,"options":["Porque serve apenas como mobiliário funcional.","Porque sua produção e seus sentidos materiais articulam memória, cosmologia e transmissão cultural.","Porque objetos sagrados não podem ser usados em práticas contemporâneas.","Porque a tradição permanece imutável quando é reconhecida como patrimônio.","Porque seu valor depende exclusivamente do mercado de arte."],"explanation":"O objeto reúne técnica, memória e cosmologia; sua produção transmite conhecimentos e sentidos entre gerações.","origin_type":"official_adaptation","origin_label":"Adaptada do ENEM 2025 · questão 44 · CC BY 4.0","origin_exam":"ENEM 2025 — 1º dia, caderno 2, questão 44","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"},{"topic_slug":"redacao-intervencao","prompt":"Adaptada da proposta de redação do ENEM 2025 sobre envelhecimento: qual encaminhamento constitui uma intervenção mais completa para combater o isolamento de pessoas idosas?","difficulty":5,"correct_position":4,"options":["Pedir que cada pessoa idosa resolva o problema sozinha.","Criar uma campanha sem informar responsável, público ou forma de acompanhamento.","Delegar toda a responsabilidade às famílias, sem apoio público.","Propor ação de órgãos de saúde e assistência com atividades acessíveis, participação comunitária e avaliação periódica, respeitando direitos.","Restringir o acesso a serviços para concentrar recursos em um único grupo."],"explanation":"A proposta identifica responsáveis e ações, prevê acessibilidade e acompanhamento e respeita direitos, articulando-se ao problema do envelhecimento e do isolamento.","origin_type":"official_adaptation","origin_label":"Adaptada da proposta de redação do ENEM 2025 · CC BY 4.0","origin_exam":"ENEM 2025 — 1º dia, caderno 2, questão Proposta de redação","origin_url":"https://riep.inep.gov.br/items/ca4bcb51-f523-495b-8b49-704c0f155ba8/full","origin_license":"CC BY 4.0 — adaptação com atribuição ao INEP"}]$official_seed$::jsonb)
    as seed(topic_slug text, prompt text, difficulty smallint, correct_position smallint, options jsonb, explanation text, origin_type text, origin_label text, origin_exam text, origin_url text, origin_license text)
),
question_seed as (
  select * from original_seed
  union all
  select * from official_seed
),
inserted_questions as (
  insert into public.question_bank_questions (topic_id, prompt, difficulty, origin_type, origin_label, origin_exam, origin_url, origin_license)
  select topic.id, seed.prompt, seed.difficulty, seed.origin_type, seed.origin_label, seed.origin_exam, seed.origin_url, seed.origin_license
  from question_seed as seed
  join public.question_bank_topics as topic on topic.slug = seed.topic_slug
  returning id, topic_id, prompt
),
inserted_options as (
  insert into public.question_bank_options (question_id, label, position)
  select question.id, option_row.label, option_row.position::smallint
  from inserted_questions as question
  join question_seed as seed on seed.prompt = question.prompt
  join public.question_bank_topics as topic on topic.id = question.topic_id and topic.slug = seed.topic_slug
  cross join lateral jsonb_array_elements_text(seed.options) with ordinality as option_row(label, position)
  returning id, question_id, position
)
insert into private.question_bank_answer_keys (question_id, correct_option_id, explanation)
select question.id, option.id, seed.explanation
from inserted_questions as question
join question_seed as seed on seed.prompt = question.prompt
join public.question_bank_topics as topic on topic.id = question.topic_id and topic.slug = seed.topic_slug
join inserted_options as option on option.question_id = question.id and option.position = seed.correct_position;
